r=Path('/workspace/8004-repair');repo=Path('/workspace/ripr-swarm');head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip();tree=subprocess.check_output(['git','rev-parse','HEAD^{tree}'],cwd=repo,text=True).strip();assert head=='a5c69b1cd2ef73d47a11163bca0432f9fe285c3d' and tree=='cc498e204e08facb92cab0d1dad36b36bddd428d';assert not subprocess.check_output(['git','status','--porcelain'],cwd=repo)
