g=json.loads((repo/'target/ripr/reports/golden-drift.json').read_text());assert g['status']=='pass' and g['drift_count']==0 and not g['violations'];md=(repo/'target/ripr/reports/goldens.md').read_text();selected=re.findall(r'^- `fixtures/([^`]+)`$',md,re.M);compared=re.findall(r'^- `([^`]+)` `check.json`: (\w+)',md,re.M);assert len(selected)==len(compared)==465 and set(selected)=={x[0] for x in compared} and all(x[1]=='pass' for x in compared)
d=r/'reports-goldens-retry';d.mkdir(exist_ok=True)
for name in ['goldens.md','golden-drift.md','golden-drift.json']:shutil.copyfile(repo/'target/ripr/reports'/name,d/name)
