paths=subprocess.check_output(['git','diff','--name-only','6b38d4e74623743d851f5dc7756725662a250e2b','HEAD'],cwd=repo,text=True).splitlines();assert not any('-verdict-corpus/cases/' in p or '-verdict-corpus/expected/' in p for p in paths);assert all(p.startswith('fixtures/inherent_receiver_async_function/') for p in paths if '/expected/' in p)
